{
  "findings": [
    {
      "ref": "[D502]",
      "area": "data",
      "claim": "A parent reports that the developer collects identifiers like Steam ID, phone model, and IP address, and may share them with third parties such as Google, Microsoft, and Valve.",
      "stance": "risk",
      "quote": "Identifiers: Steam ID for Valve players (but we do not store it); Internet or other similar network activity: gameplay information for Microsoft players; and Other: phone model for Microsoft players."
    },
    {
      "ref": "[D502]",
      "area": "data",
      "claim": "A parent reports that the developer collects personal information such as name, address, email, and payment details when using the Shop, and may share it with service providers and affiliates.",
      "stance": "risk",
      "quote": "Identifiers: first and last name, billing address, shipping address, Internet Protocol address, and email address; Commercial information: payment information and purchase history, including value and details of purchase."
    },
    {
      "ref": "[D502]",
      "area": "data",
      "claim": "A parent reports that the developer may retain personal data indefinitely if it is needed for legal, safety, or service continuity reasons, even after the game is discontinued.",
      "stance": "risk",
      "quote": "it is our policy to delete your Personal Data if we stop operating our Game or the feature through which the Personal Data was acquired."
    },
    {
      "ref": "[D502]",
      "area": "age_gating",
      "claim": "A parent reports that the developer states it does not knowingly collect personal data from children and asks parents to contact them if a child has provided data.",
      "stance": "mitigation",
      "quote": "A “Child” is a person under the age needed to consent to the processing of Personal Data in their country of residence (for example, 13 years old in the United States and between 13 and 16 years old in the European Union). We do not knowingly collect Personal Data from a Child. If you are a Child, do not submit any Personal Data to us. If you become aware that a Child has provided us with Personal Data, please contact us at (/cdn-cgi/l/email-protection) or 701 N. 36th St., Suite 200, Seattle, WA 98103, so we may delete that Personal Data."
    }
  ]
}
